import { useState, useMemo, useEffect } from "react";
import { useLazyQuery } from "@apollo/client";
import { Q, PRESETS } from "../../../apollo/gql.js";
import { useApiQuery } from "../../../apollo/useApi.js";
import {
  StatCard,
  PageHeader,
  FormField,
  Spinner,
} from "../../../components/common/index.jsx";
import { getChapterName } from "../../../utils/helpers.js";
import { buildSpanProgressReport } from "../../../utils/progressReport.js";
import SpanProgressReportView from "./components/SpanProgressReportView.jsx";

const REPORT_LIMIT = 5000;

const REPORT_ACTIVITIES_QUERY = Q.activities.list(PRESETS.activityReportDetail, {
  pagination: "totalDocuments",
});

const REPORT_SPAN_QUERY = Q.spans.get(PRESETS.spanReport);

const FALLBACK_COLORS = [
  "#3B82F6",
  "#10B981",
  "#F59E0B",
  "#EF4444",
  "#8B5CF6",
  "#06B6D4",
  "#F97316",
  "#84CC16",
  "#EC4899",
  "#14B8A6",
];

export default function ReportsDashboard() {
  const today = new Date().toISOString().slice(0, 10);
  const firstOfMonth = today.slice(0, 8) + "01";
  const [from, setFrom] = useState(firstOfMonth);
  const [to, setTo] = useState(today);
  const [spanId, setSpanId] = useState("");
  const [reportSpanId, setReportSpanId] = useState("");

  useEffect(() => {
    setReportSpanId("");
  }, [spanId, from, to]);

  const { data: spansListData, loading: spansListLoading } = useApiQuery(
    Q.spans.list,
    {
      fields: PRESETS.spanReport,
      variables: { page: 1, limit: 200 },
      fetchPolicy: "cache-and-network",
    },
  );

  const spans = spansListData?.spans?.data ?? [];
  const selectedSpan = spans.find((s) => s._id === spanId) ?? null;

  const [
    fetchActivities,
    {
      data: activitiesData,
      loading: activitiesLoading,
      error: activitiesError,
    },
  ] = useLazyQuery(REPORT_ACTIVITIES_QUERY, { fetchPolicy: "network-only" });

  const [
    fetchReportSpan,
    {
      data: reportSpanData,
      loading: reportSpanLoading,
      error: reportSpanError,
    },
  ] = useLazyQuery(REPORT_SPAN_QUERY, { fetchPolicy: "network-only" });

  const loading = activitiesLoading || spansListLoading || reportSpanLoading;

  const generate = () => {
    if (!spanId) return;
    setReportSpanId(spanId);
    fetchReportSpan({ variables: { id: spanId } });
    fetchActivities({
      variables: {
        limit: REPORT_LIMIT,
        span: [spanId],
        fromDate: new Date(from + "T00:00:00").toISOString(),
        toDate: new Date(to + "T23:59:59").toISOString(),
      },
    });
  };

  const reportSpan =
    reportSpanData?.span ??
    spans.find((s) => s._id === reportSpanId) ??
    selectedSpan;

  const reportData = useMemo(() => {
    const activities = activitiesData?.activities?.data;
    if (!activities || !reportSpan) return null;

    const chapterColorMap = {};
    for (const ch of reportSpan.chapters ?? []) {
      if (ch.name && ch.color) chapterColorMap[ch.name] = ch.color;
    }

    const total = activities.length;
    const approved = activities.filter((e) => e.status === "APPROVED").length;
    const rejected = activities.filter((e) => e.status === "REJECTED").length;
    const submitted = activities.filter((e) => e.status === "SUBMITTED").length;

    const chapterMap = {};
    for (const a of activities) {
      const name = getChapterName(a.chapter);
      if (!name) continue;
      chapterMap[name] = (chapterMap[name] ?? 0) + 1;
    }

    const breakdown = Object.entries(chapterMap)
      .map(([name, count], i) => ({
        cat: name,
        count,
        color:
          chapterColorMap[name] ?? FALLBACK_COLORS[i % FALLBACK_COLORS.length],
      }))
      .sort((a, b) => b.count - a.count);

    const progressRows = buildSpanProgressReport(reportSpan, activities, {
      fromDate: from,
      toDate: to,
    });

    return {
      total,
      approved,
      rejected,
      submitted,
      breakdown,
      progressRows,
      spanName: reportSpan.name,
      projectName: reportSpan.project?.name,
    };
  }, [activitiesData, reportSpan, from, to]);


  
  return (
    <div className="fade-up">
      <PageHeader
        title="Reports"
        subtitle="Generate progress and compliance reports"
      />

      <div className="card" style={{ marginBottom: 16 }}>
        <div className="card-header">
          <span className="card-title">Report Parameters</span>
        </div>
        <div className="form-row">
          <FormField
            label="Span"
            description="Activities are filtered to this span only"
          >
            <select
              className="form-control"
              value={spanId}
              onChange={(e) => setSpanId(e.target.value)}
              disabled={spansListLoading}
            >
              <option value="">
                {spansListLoading ? "Loading spans…" : "Select a span…"}
              </option>
              {spans.map((s) => (
                <option key={s._id} value={s._id}>
                  {s.name}
                  {s.project?.name ? ` · ${s.project.name}` : ""}
                </option>
              ))}
            </select>
          </FormField>
        </div>
        <div className="form-row">
          <FormField label="From Date" description="Start date of the report">
            <input
              className="form-control"
              type="date"
              value={from}
              onChange={(e) => setFrom(e.target.value)}
            />
          </FormField>
          <FormField label="To Date" description="End date of the report">
            <input
              className="form-control"
              type="date"
              value={to}
              onChange={(e) => setTo(e.target.value)}
            />
          </FormField>
        </div>
        <div style={{ display: "flex", gap: 10, flexWrap: "wrap" }}>
          {[
            ["📊 Progress Report", "primary"],
            ["📋 Compliance Report", "outline"],
            ["💰 Financial Report", "outline"],
          ].map(([label, type]) => (
            <button
              key={label}
              className={`btn btn-${type}`}
              onClick={generate}
              disabled={loading || !spanId}
            >
              {loading && type === "primary" ? (
                <Spinner size={14} color="var(--navy)" />
              ) : (
                label
              )}
            </button>
          ))}
        </div>
        {!spanId && !spansListLoading && spans.length > 0 && (
          <p style={{ fontSize: 11, color: "var(--text3)", marginTop: 10 }}>
            Select a span to generate the report.
          </p>
        )}
        {!spansListLoading && spans.length === 0 && (
          <p style={{ fontSize: 11, color: "var(--yellow)", marginTop: 10 }}>
            No spans available. Create a span first.
          </p>
        )}
      </div>

      {(activitiesError || reportSpanError) && (
        <div
          className="card"
          style={{ marginBottom: 16, color: "var(--red)", fontSize: 13 }}
        >
          Failed to fetch report data:{" "}
          {activitiesError?.message ?? reportSpanError?.message}
        </div>
      )}

      {reportData && reportSpanId === spanId && (
        <div className="fade-up">
          <div className="card" style={{ marginBottom: 16 }}>
            <div className="card-header">
              <span className="card-title">Progress Report</span>
              <span style={{ fontSize: 11, color: "var(--text2)" }}>
                {reportData.spanName ?? "—"}
                {reportData.projectName
                  ? ` · ${reportData.projectName}`
                  : ""}{" "}
                · {from} to {to}
              </span>
            </div>

            <div className="stats-grid">
              <StatCard
                icon="📋"
                number={reportData.total}
                label="Total Entries"
                color="var(--blue)"
              />
              <StatCard
                icon="✅"
                number={reportData.approved}
                label="Approved"
                color="var(--green)"
              />
              <StatCard
                icon="❌"
                number={reportData.rejected}
                label="Rejected"
                color="var(--red)"
              />
              <StatCard
                icon="⏳"
                number={reportData.submitted}
                label="Submitted"
                color="var(--yellow)"
              />
            </div>

            {reportData.breakdown.length > 0 && (
              <div style={{ marginTop: 16 }}>
                <div
                  className="card-title"
                  style={{ fontSize: 13, marginBottom: 12 }}
                >
                  Chapter-wise Breakdown
                </div>
                {reportData.breakdown.map((b) => (
                  <div key={b.cat} style={{ marginBottom: 12 }}>
                    <div
                      style={{
                        display: "flex",
                        justifyContent: "space-between",
                        fontSize: 12,
                        marginBottom: 4,
                      }}
                    >
                      <span
                        style={{
                          display: "flex",
                          alignItems: "center",
                          gap: 6,
                        }}
                      >
                        <span
                          style={{
                            width: 8,
                            height: 8,
                            borderRadius: "50%",
                            background: b.color,
                            display: "inline-block",
                          }}
                        />
                        {b.cat}
                      </span>
                      <span style={{ color: "var(--text2)" }}>
                        {b.count} entr{b.count === 1 ? "y" : "ies"}
                      </span>
                    </div>
                    <div
                      style={{
                        height: 5,
                        background: "rgba(255,255,255,.07)",
                        borderRadius: 3,
                        overflow: "hidden",
                      }}
                    >
                      <div
                        style={{
                          width: `${reportData.total > 0 ? (b.count / reportData.total) * 100 : 0}%`,
                          height: "100%",
                          background: b.color,
                          borderRadius: 3,
                          transition: "width .5s",
                        }}
                      />
                    </div>
                  </div>
                ))}
              </div>
            )}

            {reportData.breakdown.length === 0 && (
              <div
                style={{ fontSize: 12, color: "var(--text3)", marginTop: 16 }}
              >
                No entries found for this span in the selected date range.
              </div>
            )}

            <div
              style={{
                marginTop: 20,
                paddingTop: 20,
                borderTop: "1px solid var(--border)",
              }}
            >
              <SpanProgressReportView
                rows={reportData.progressRows}
                spanName={reportData.spanName}
              />
            </div>

            <div
              style={{
                display: "flex",
                gap: 10,
                marginTop: 16,
                paddingTop: 14,
                borderTop: "1px solid var(--border)",
              }}
            >
              <button className="btn btn-outline btn-sm">📊 Export XLSX</button>
              <button className="btn btn-outline btn-sm">📧 Email Report</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
