/** Chapter from API may be a string (legacy) or { _id, name }. */
export function getChapterName(chapter) {
  if (chapter == null) return null;
  if (typeof chapter === "string") return chapter;
  if (typeof chapter === "object") return chapter.name ?? null;
  return String(chapter);
}

export function getChapterId(chapter) {
  if (chapter == null) return null;
  if (typeof chapter === "string") return chapter;
  if (typeof chapter === "object") return chapter._id ?? null;
  return null;
}

export function deepClean(value,stripKeys=STRIP_KEYS) {
  if (Array.isArray(value)) {
    return value.map(deepClean);
  }
  if (value !== null && typeof value === 'object') {
    return Object.fromEntries(
      Object.entries(value)
        .filter(([k]) => !STRIP_KEYS.has(k))
        .map(([k, v]) => [k, deepClean(v)])
    );
  }
  return value; // primitive — keep as-is
}
export const STRIP_KEYS = new Set([
  '_id',
  '__typename',
  'localId',
  'createdAt',
  'updatedAt',
  'cumulativeProgress',
]);