/**
 * Composable GraphQL selection strings — components pick only what they need.
 *
 * @example
 * import { F, pick, PRESETS } from './fields.js';
 * useQuery(Q.activities.list(PRESETS.activityTable), { variables });
 *
 * @example custom
 * useQuery(Q.spans.list(pick(F.span.id, F.span.name, F.span.chapters)), { variables });
 */

export const pick = (...parts) =>
  parts
    .flat()
    .filter(Boolean)
    .join('\n      ');

